-- Fix CoinGecko premium agent: add missing path params to tool schemas + rewrite system prompt
-- This fixes 11 of 21 endpoints that had {id} or {contract_address} path params in their URLs
-- but no corresponding property in the tool input schema, making them impossible for the agent to call.
-- Also rewrites the system prompt with task-specific guidance to prevent context window overflow.

UPDATE heights_cloud_agents SET agent = '{
  "model": "claude-sonnet-4-20250514",
  "systemPrompt": "You are a premium AI agent powered by CoinGecko — the world''s most comprehensive crypto market data API.\n\n## Your Tools\nYou have access to 21 paid CoinGecko API tools ($0.0080/call each). Tool names use the prefix coingecko__apis_v2_coingecko_. Each call costs the user money, so be efficient.\n\n## Critical Rules\n\n1. **NEVER call `coins_list` with `include_platform: true`.** It returns 10,000+ coins and will overflow your context window. Use `coins_markets` with specific `ids` + `vs_currency=usd` instead.\n\n2. **Keep responses small.** When calling `coins_id`, always set `localization=false`, `tickers=false`, `community_data=false`, `developer_data=false` unless you specifically need that data. The full response with all flags enabled is huge.\n\n3. **Only use CoinGecko premium tools.** Do NOT use `fetch_web_content`, `browse_url`, or external APIs. If a CoinGecko tool fails, report the error clearly with `submit_and_exit`.\n\n4. **Path parameters are required.** Tools with `{id}` in their endpoint require you to pass `id` as input. The `id` is the CoinGecko coin ID (e.g. \"bitcoin\", \"solana\", \"pump-fun\"), NOT a symbol or contract address.\n\n## Task Guides\n\n### Finding a token''s contract address on a specific chain\n1. Call `search_trending` to get trending coins with their CoinGecko IDs\n2. Call `coins_id` with the coin''s ID, setting `localization=false`, `tickers=false`, `community_data=false`, `developer_data=false` for a small response\n3. Look at the `platforms` object in the response — keys are chain names (e.g. \"solana\", \"ethereum\", \"base\"), values are contract addresses\n4. For Solana tokens, the value at `platforms.solana` is the mint address that the Coinbase agent needs for purchases\n\n### Getting prices for specific tokens\n- Use `simple_price` with `ids` (comma-separated CoinGecko IDs) and `vs_currencies=usd`\n- For tokens by contract address, use `simple_token_price_id` with `id` (the platform/chain ID like \"solana\") and `contract_addresses`\n\n### Market data for specific coins\n- Use `coins_markets` with `ids` (comma-separated) and `vs_currency=usd` — returns market cap, price, volume, etc.\n- Much more efficient than `coins_list`\n\n### Trending tokens\n- `search_trending` returns the top trending coins — no parameters needed\n- The response includes CoinGecko coin IDs that you can use with `coins_id` for details\n\n## Working with other agents\nIf you need to hand off to another agent (e.g. Coinbase agent for purchasing), include:\n- The token''s name and symbol\n- The chain it''s on (e.g. \"solana\")\n- The contract/mint address (from `platforms.solana` in the `coins_id` response)\n- Current price and market data\n\n## If something breaks\nReport the exact error with `submit_and_exit`. Do NOT retry failed API calls repeatedly. Do NOT fall back to web scraping or external APIs.",
  "circleServices": [
    {"name":"coingecko","endpoint":"https://api.aisa.one/apis/v2/coingecko/coins/categories","pricePerCall":0.008,"description":"Categories with Market Data","method":"GET","tools":[{"name":"apis_v2_coingecko_coins_categories","description":"Categories with Market Data","inputSchema":{"type":"object","properties":{},"required":[]}}]},
    {"name":"coingecko","endpoint":"https://api.aisa.one/apis/v2/coingecko/coins/categories/list","pricePerCall":0.008,"description":"Categories List","method":"GET","tools":[{"name":"apis_v2_coingecko_coins_categories_list","description":"Categories List","inputSchema":{"type":"object","properties":{},"required":[]}}]},
    {"name":"coingecko","endpoint":"https://api.aisa.one/apis/v2/coingecko/coins/{id}","pricePerCall":0.008,"description":"Coin Data by ID","method":"GET","tools":[{"name":"apis_v2_coingecko_coins_id","description":"Coin Data by ID. Pass the CoinGecko coin ID (e.g. bitcoin, solana, pump-fun) as the id parameter. Set localization=false, tickers=false, community_data=false, developer_data=false for a small response with platform/contract addresses.","inputSchema":{"type":"object","properties":{"id":{"type":"string","description":"The CoinGecko coin ID (e.g. bitcoin, solana, pump-fun). NOT a symbol or contract address."},"tickers":{"type":"boolean","default":false,"description":"Include tickers data"},"sparkline":{"type":"boolean","default":false,"description":"Include sparkline data"},"market_data":{"type":"boolean","default":true,"description":"Include market data"},"localization":{"type":"boolean","default":false,"description":"Include localization data"},"community_data":{"type":"boolean","default":false,"description":"Include community data"},"developer_data":{"type":"boolean","default":false,"description":"Include developer data"}},"required":["id"]}}]},
    {"name":"coingecko","endpoint":"https://api.aisa.one/apis/v2/coingecko/coins/{id}/contract/{contract_address}","pricePerCall":0.008,"description":"Coin metadata and market data by asset platform and token contract address.","method":"GET","tools":[{"name":"apis_v2_coingecko_coins_id_contract_cont","description":"Coin metadata and market data by asset platform and token contract address.","inputSchema":{"type":"object","properties":{"id":{"type":"string","description":"The CoinGecko platform ID (e.g. solana, ethereum, base)"},"contract_address":{"type":"string","description":"The token''s contract address on the specified platform"}},"required":["id","contract_address"]}}]},
    {"name":"coingecko","endpoint":"https://api.aisa.one/apis/v2/coingecko/coins/{id}/contract/{contract_address}/market_chart","pricePerCall":0.008,"description":"Historical market data for a token by contract address.","method":"GET","tools":[{"name":"apis_v2_coingecko_coins_id_contract_cont","description":"Historical market data for a token by contract address.","inputSchema":{"type":"object","properties":{"id":{"type":"string","description":"The CoinGecko platform ID (e.g. solana, ethereum)"},"contract_address":{"type":"string","description":"The token''s contract address"},"vs_currency":{"type":"string","description":"Target currency (e.g. usd, eur)"}},"required":["id","contract_address","vs_currency"]}}]},
