    {"name":"coingecko","endpoint":"https://api.aisa.one/apis/v2/coingecko/coins/{id}/ohlc","pricePerCall":0.008,"description":"Coin OHLC","method":"GET","tools":[{"name":"apis_v2_coingecko_coins_id_ohlc","description":"Coin OHLC","inputSchema":{"type":"object","properties":{"id":{"type":"string","description":"The CoinGecko coin ID (e.g. bitcoin, solana)"},"vs_currency":{"type":"string","description":"Target currency (e.g. usd)"},"days":{"type":"string","description":"Number of days (e.g. 1, 7, 30)"}},"required":["id","vs_currency","days"]}}]},
    {"name":"coingecko","endpoint":"https://api.aisa.one/apis/v2/coingecko/coins/{id}/tickers","pricePerCall":0.008,"description":"Coin Tickers","method":"GET","tools":[{"name":"apis_v2_coingecko_coins_id_tickers","description":"Coin Tickers","inputSchema":{"type":"object","properties":{"id":{"type":"string","description":"The CoinGecko coin ID (e.g. bitcoin, solana)"},"page":{"type":"integer","description":"Page number"},"depth":{"type":"integer","description":"Depth"},"order":{"type":"string","description":"Order"},"exchange_ids":{"type":"string","description":"Comma-separated exchange IDs"}},"required":["id"]}}]},
    {"name":"coingecko","endpoint":"https://api.aisa.one/apis/v2/coingecko/coins/list","pricePerCall":0.008,"description":"Coins List (ID Map). WARNING: Do NOT set include_platform=true — it returns 10,000+ coins and overflows context. Use coins_markets instead for specific coins.","method":"GET","tools":[{"name":"apis_v2_coingecko_coins_list","description":"Coins List (ID Map). WARNING: Do NOT set include_platform=true — returns 10,000+ coins. Use coins_markets for specific coins instead.","inputSchema":{"type":"object","properties":{"include_platform":{"type":"boolean","default":false,"description":"Include platform + contract addresses. WARNING: Setting true returns 10,000+ coins — do NOT use this."}},"required":[]}}]},
    {"name":"coingecko","endpoint":"https://api.aisa.one/apis/v2/coingecko/coins/markets","pricePerCall":0.008,"description":"Coins Markets — preferred way to get market data for specific coins. Pass comma-separated CoinGecko IDs.","method":"GET","tools":[{"name":"apis_v2_coingecko_coins_markets","description":"Coins Markets — preferred way to get market data for specific coins. Pass comma-separated CoinGecko IDs.","inputSchema":{"type":"object","properties":{"ids":{"type":"string","description":"Comma-separated CoinGecko coin IDs (e.g. bitcoin,solana,pump-fun)"},"page":{"type":"integer","default":1,"description":"Page number"},"order":{"type":"enum","default":"market_cap_desc","description":"Sort order"},"category":{"type":"string","description":"Filter by category"},"per_page":{"type":"integer","default":100,"maximum":250,"minimum":1,"description":"Results per page"},"sparkline":{"type":"boolean","default":false,"description":"Include sparkline"},"vs_currency":{"type":"string","description":"Target currency (e.g. usd)"},"price_change_percentage":{"type":"string","description":"Comma-separated windows: 1h,24h,7d,14d,30d,200d,1y"}},"required":["vs_currency"]}}]},
